"""A small checkers engine."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Literal

BoardSquare = Literal[" ", "w", "W", "b", "B"]
Player = Literal["w", "b"]

BOARD_SIZE = 8


@dataclass(frozen=True, slots=True)
class Move:
    path: tuple[tuple[int, int], ...]

    @property
    def start(self) -> tuple[int, int]:
        return self.path[0]

    @property
    def end(self) -> tuple[int, int]:
        return self.path[-1]

    @property
    def captures(self) -> tuple[tuple[int, int], ...]:
        return tuple(
            ((a + c) // 2, (b + d) // 2)
            for (a, b), (c, d) in zip(self.path, self.path[1:])
            if abs(a - c) == 2 and abs(b - d) == 2
        )


@dataclass(frozen=True, slots=True)
class GameState:
    board: tuple[tuple[BoardSquare, ...], ...]
    turn: Player = "w"

    @staticmethod
    def initial() -> "GameState":
        board = [[" " for _ in range(BOARD_SIZE)] for _ in range(BOARD_SIZE)]
        for r in range(3):
            for c in range(BOARD_SIZE):
                if (r + c) % 2 == 1:
                    board[r][c] = "b"
        for r in range(5, 8):
            for c in range(BOARD_SIZE):
                if (r + c) % 2 == 1:
                    board[r][c] = "w"
        return GameState(tuple(tuple(row) for row in board), "w")

    @staticmethod
    def from_rows(rows: Iterable[str], turn: Player = "w") -> "GameState":
        board = tuple(tuple(_normalize_square(ch) for ch in row) for row in rows)
        if len(board) != BOARD_SIZE or any(len(row) != BOARD_SIZE for row in board):
            raise ValueError("board must be 8x8")
        return GameState(board, turn)

    def legal_moves(self) -> list[Move]:
        captures: list[Move] = []
        moves: list[Move] = []
        for r in range(BOARD_SIZE):
            for c in range(BOARD_SIZE):
                if _owner(self.board[r][c]) != self.turn:
                    continue
                captures.extend(self._captures_from((r, c)))
                if not captures:
                    moves.extend(self._simple_moves_from((r, c)))
        return captures or moves

    def apply(self, move: Move) -> "GameState":
        legal = self.legal_moves()
        if move not in legal:
            raise ValueError("illegal move")
        board = [list(row) for row in self.board]
        sr, sc = move.start
        piece = board[sr][sc]
        board[sr][sc] = " "
        for (r1, c1), (r2, c2) in zip(move.path, move.path[1:]):
            if abs(r1 - r2) == 2:
                board[(r1 + r2) // 2][(c1 + c2) // 2] = " "
        er, ec = move.end
        if piece == "w" and er == 0:
            piece = "W"
        elif piece == "b" and er == BOARD_SIZE - 1:
            piece = "B"
        board[er][ec] = piece
        return GameState(tuple(tuple(row) for row in board), "b" if self.turn == "w" else "w")

    def _simple_moves_from(self, pos: tuple[int, int]) -> list[Move]:
        r, c = pos
        piece = self.board[r][c]
        out: list[Move] = []
        for dr, dc in _directions(piece):
            nr, nc = r + dr, c + dc
            if _in_bounds(nr, nc) and self.board[nr][nc] == " ":
                out.append(Move((pos, (nr, nc))))
        return out

    def _captures_from(self, pos: tuple[int, int]) -> list[Move]:
        r, c = pos
        piece = self.board[r][c]
        out: list[Move] = []

        def explore(path: tuple[tuple[int, int], ...], board: list[list[BoardSquare]]) -> None:
            rr, cc = path[-1]
            found = False
            for dr, dc in _directions(piece):
                mr, mc = rr + dr, cc + dc
                er, ec = rr + 2 * dr, cc + 2 * dc
                if not (_in_bounds(mr, mc) and _in_bounds(er, ec)):
                    continue
                if _owner(board[mr][mc]) == _other(self.turn) and board[er][ec] == " ":
                    found = True
                    next_board = [row[:] for row in board]
                    next_board[rr][cc] = " "
                    next_board[mr][mc] = " "
                    next_board[er][ec] = piece
                    explore(path + ((er, ec),), next_board)
            if not found and len(path) > 1:
                out.append(Move(path))

        explore((pos,), [list(row) for row in self.board])
        return out


def _normalize_square(ch: str) -> BoardSquare:
    return ch if ch in {" ", "w", "W", "b", "B"} else " "


def _owner(square: BoardSquare) -> Player | None:
    if square in {"w", "W"}:
        return "w"
    if square in {"b", "B"}:
        return "b"
    return None


def _other(player: Player) -> Player:
    return "b" if player == "w" else "w"


def _in_bounds(r: int, c: int) -> bool:
    return 0 <= r < BOARD_SIZE and 0 <= c < BOARD_SIZE


def _directions(square: BoardSquare) -> list[tuple[int, int]]:
    if square == "w":
        return [(-1, -1), (-1, 1)]
    if square == "b":
        return [(1, -1), (1, 1)]
    if square in {"W", "B"}:
        return [(-1, -1), (-1, 1), (1, -1), (1, 1)]
    return []
